"use client";
import Link from "next/link";
import { ArrowLeft, CheckCircle2, IndianRupee, Sparkles } from "lucide-react";
import { useState } from "react";
const API=process.env.NEXT_PUBLIC_API_URL||"http://127.0.0.1:8000";
type Result={predicted_price:number;price_range:{min:number;max:number};confidence:string;comparison_basis?:string;comparable_products_count:number;comparable_products:{product_name:string;selling_price:number;material?:string;product_type?:string;source?:string;url?:string}[]};
export default function PriceEstimator(){const [name,setName]=useState("Handmade Bamboo Stool"),[material,setMaterial]=useState("bamboo"),[type,setType]=useState("stool"),[mrp,setMrp]=useState("1500"),[result,setResult]=useState<Result|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState("");async function estimate(){setLoading(true);setError("");try{const r=await fetch(`${API}/api/ml/price-estimate`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({product_name:name,material,product_type:type,mrp:Number(mrp)})});if(!r.ok)throw new Error();const d=await r.json();setResult(d.data??d)}catch{setError("Could not reach the ML price service. Make sure FastAPI is running on port 8000.")}finally{setLoading(false)}}return <div className="page-shell"><div className="container tool-wrap"><Link href="/" className="card-link"><ArrowLeft size={15}/> Back home</Link><div className="tool-header"><div><div className="section-kicker">PRICE INTELLIGENCE</div><h1 className="section-title">Price, with evidence.</h1><p className="section-desc">A model estimate is combined with observed comparable listings. The range is an approximation, not a fixed artisan price.</p></div><div className="ai-icon"><IndianRupee size={25}/></div></div><div className="tool-card"><div className="field-grid"><div className="field full"><label>Product name</label><input value={name} onChange={e=>setName(e.target.value)}/></div><div className="field"><label>Material</label><input value={material} onChange={e=>setMaterial(e.target.value)}/></div><div className="field"><label>Product type</label><input value={type} onChange={e=>setType(e.target.value)}/></div><div className="field"><label>Reference MRP</label><input type="number" value={mrp} onChange={e=>setMrp(e.target.value)}/></div></div><button className="btn btn-primary" style={{marginTop:18}} onClick={estimate} disabled={loading}>{loading?<><span className="spinner"/> Estimating...</>:<><Sparkles size={16}/> Estimate market range</>}</button>{error&&<p style={{color:"#a9523c"}}>{error}</p>}{result&&<div className="result"><div className="eyebrow"><CheckCircle2 size={14}/> Model + market evidence</div><div className="result-price">₹{result.predicted_price.toLocaleString("en-IN")}</div><div className="range">Observed estimate range · ₹{result.price_range.min.toLocaleString("en-IN")} – ₹{result.price_range.max.toLocaleString("en-IN")}</div><div className="result-grid"><div className="result-stat"><small>Confidence</small><strong>{result.confidence}</strong></div><div className="result-stat"><small>Comparison basis</small><strong>{result.comparison_basis??"Market comparables"}</strong></div><div className="result-stat"><small>Comparable listings</small><strong>{result.comparable_products_count}</strong></div></div>{result.comparable_products?.length>0&&<div className="sources"><div className="section-kicker">Comparable listings</div>{result.comparable_products.map((p,i)=><div className="source" key={i}><strong>{p.product_name}</strong><small>₹{Number(p.selling_price).toLocaleString("en-IN")} · {p.material??"—"} · {p.product_type??"—"}{p.url&&<> · <a href={p.url} target="_blank" rel="noreferrer">View listing</a></>}</small></div>)}</div>}</div>}</div></div></div>}
